void *memmove(void *dest, const void *src, size_t n) /* <=== memmove */ 
{
	if ((const char *)src >= (char *)dest + n
	    || (char *)dest >= (const char *)src + n) {
		/* We found no overlap, so let memcpy do all the heavy
		 * lifting (prefetching, etc.)
		 */
		return memcpy(dest, src, n);
	}

	if (n != 0) {
		const uint8_t *in;
		uint8_t x;
		uint8_t *out;
		int stride;

		if (src < dest) {
			/* copy backwards */
			in = (const uint8_t *)src + n - 1;
			out = (uint8_t *)dest + n - 1;
			stride = -1;
		} else {
			/* copy forwards */
			in = (const uint8_t *)src;
			out = (uint8_t *)dest;
			stride = 1;
		}

		/* Manually software-pipeline this loop. */
		x = *in;
		in += stride;

		while (--n != 0) {
			*out = x;
			out += stride;
			x = *in;
			in += stride;
		}

		*out = x;
	}

	return dest;
}

static __inline__ int /* <=== test_bit */ 
test_bit (int nr, const volatile void *addr)
{
	return 1 & (((const volatile __u32 *) addr)[nr >> 5] >> (nr & 31));
}

static inline int usb_endpoint_type(const struct usb_endpoint_descriptor *epd) /* <=== usb_endpoint_type */ 
{
	return epd->bmAttributes & USB_ENDPOINT_XFERTYPE_MASK;
}

static inline void clear_bit(int nr, volatile void * addr) /* <=== clear_bit */ 
{
	unsigned long *p = ((unsigned long *)addr) + nr / BITS_PER_LONG;
	unsigned long tmp;

	if (__builtin_constant_p(nr)) {
		asm volatile(
			"1:	ssrf	5\n"
			"	ld.w	%0, %2\n"
			"	cbr	%0, %3\n"
			"	stcond	%1, %0\n"
			"	brne	1b"
			: "=&r"(tmp), "=o"(*p)
			: "m"(*p), "i"(nr)
			: "cc");
	} else {
		unsigned long mask = 1UL << (nr % BITS_PER_LONG);
		asm volatile(
			"1:	ssrf	5\n"
			"	ld.w	%0, %2\n"
			"	andn	%0, %3\n"
			"	stcond	%1, %0\n"
			"	brne	1b"
			: "=&r"(tmp), "=o"(*p)
			: "m"(*p), "r"(mask)
			: "cc");
	}
}

